class Solution {
    public void solveSudoku(char[][] board) {
        boolean[][] rows = new boolean[9][10];
        boolean[][] columns = new boolean[9][10];
        boolean[][] boxes = new boolean[9][10];
        List<int[]> emptyCells = new ArrayList<>();

        for (int row = 0; row < 9; row++) {
            for (int col = 0; col < 9; col++) {
                if (board[row][col] == '.') {
                    emptyCells.add(new int[]{row, col});
                } else {
                    int digit = board[row][col] - '0';
                    rows[row][digit] = true;
                    columns[col][digit] = true;
                    boxes[boxIndex(row, col)][digit] = true;
                }
            }
        }
        solve(board, emptyCells, 0, rows, columns, boxes);
    }

    private boolean solve(char[][] board, List<int[]> emptyCells, int index,
                          boolean[][] rows, boolean[][] columns, boolean[][] boxes) {
        if (index == emptyCells.size()) {
            return true;
        }
        int row = emptyCells.get(index)[0];
        int col = emptyCells.get(index)[1];
        int box = boxIndex(row, col);
        for (int digit = 1; digit <= 9; digit++) {
            if (rows[row][digit] || columns[col][digit] || boxes[box][digit]) {
                continue;
            }
            board[row][col] = (char) ('0' + digit);
            rows[row][digit] = true;
            columns[col][digit] = true;
            boxes[box][digit] = true;
            if (solve(board, emptyCells, index + 1, rows, columns, boxes)) {
                return true;
            }
            board[row][col] = '.';
            rows[row][digit] = false;
            columns[col][digit] = false;
            boxes[box][digit] = false;
        }
        return false;
    }

    private int boxIndex(int row, int col) {
        return (row / 3) * 3 + col / 3;
    }
}

