class Solution {
    private static final int FULL_MASK = (1 << 9) - 1;
    private final int[] rows = new int[9];
    private final int[] columns = new int[9];
    private final int[] boxes = new int[9];
    private final List<int[]> emptyCells = new ArrayList<>();

    public void solveSudoku(char[][] board) {
        for (int row = 0; row < 9; row++) {
            for (int col = 0; col < 9; col++) {
                if (board[row][col] == '.') {
                    emptyCells.add(new int[]{row, col});
                    continue;
                }
                int bit = 1 << (board[row][col] - '1');
                rows[row] |= bit;
                columns[col] |= bit;
                boxes[boxIndex(row, col)] |= bit;
            }
        }
        solve(board, 0);
    }

    private boolean solve(char[][] board, int index) {
        if (index == emptyCells.size()) {
            return true;
        }
        int row = emptyCells.get(index)[0];
        int col = emptyCells.get(index)[1];
        int box = boxIndex(row, col);
        int candidates = FULL_MASK & ~(rows[row] | columns[col] | boxes[box]);
        while (candidates != 0) {
            int bit = candidates & -candidates;
            int digit = Integer.numberOfTrailingZeros(bit);
            place(board, row, col, box, bit, (char) ('1' + digit));
            if (solve(board, index + 1)) {
                return true;
            }
            remove(board, row, col, box, bit);
            candidates -= bit;
        }
        return false;
    }

    private void place(char[][] board, int row, int col, int box, int bit, char digit) {
        board[row][col] = digit;
        rows[row] |= bit;
        columns[col] |= bit;
        boxes[box] |= bit;
    }

    private void remove(char[][] board, int row, int col, int box, int bit) {
        board[row][col] = '.';
        rows[row] ^= bit;
        columns[col] ^= bit;
        boxes[box] ^= bit;
    }

    private int boxIndex(int row, int col) {
        return (row / 3) * 3 + col / 3;
    }
}

class Solution {
    private static final int FULL_MASK = (1 << 9) - 1;
    private final int[] rows = new int[9];
    private final int[] columns = new int[9];
    private final int[] boxes = new int[9];

    public void solveSudoku(char[][] board) {
        for (int row = 0; row < 9; row++) {
            for (int col = 0; col < 9; col++) {
                if (board[row][col] == '.') {
                    continue;
                }
                int bit = 1 << (board[row][col] - '1');
                rows[row] |= bit;
                columns[col] |= bit;
                boxes[boxIndex(row, col)] |= bit;
            }
        }
        solve(board);
    }

    private boolean solve(char[][] board) {
        int bestRow = -1;
        int bestCol = -1;
        int bestCandidates = 0;
        int fewest = 10;

        for (int row = 0; row < 9; row++) {
            for (int col = 0; col < 9; col++) {
                if (board[row][col] != '.') {
                    continue;
                }
                int candidates = FULL_MASK & ~(rows[row] | columns[col] | boxes[boxIndex(row, col)]);
                int count = Integer.bitCount(candidates);
                if (count == 0) {
                    return false;
                }
                if (count < fewest) {
                    fewest = count;
                    bestRow = row;
                    bestCol = col;
                    bestCandidates = candidates;
                }
            }
        }

        if (bestRow == -1) {
            return true;
        }
        int box = boxIndex(bestRow, bestCol);
        while (bestCandidates != 0) {
            int bit = bestCandidates & -bestCandidates;
            int digit = Integer.numberOfTrailingZeros(bit);
            board[bestRow][bestCol] = (char) ('1' + digit);
            rows[bestRow] |= bit;
            columns[bestCol] |= bit;
            boxes[box] |= bit;
            if (solve(board)) {
                return true;
            }
            boxes[box] ^= bit;
            columns[bestCol] ^= bit;
            rows[bestRow] ^= bit;
            board[bestRow][bestCol] = '.';
            bestCandidates -= bit;
        }
        return false;
    }

    private int boxIndex(int row, int col) {
        return (row / 3) * 3 + col / 3;
    }
}
